/**
 * Seeds the database from seed/catalog.json (generated by scripts/prepare-content.py
 * from the old trumee.in Shopify store). Idempotent: skips if products exist unless --reset.
 *
 *   npm run db:seed            # first-time import
 *   npm run db:seed -- --reset # wipe catalog/content and re-import
 */
import "dotenv/config";
import bcrypt from "bcryptjs";
import { readFileSync } from "node:fs";
import path from "node:path";
import { sql } from "drizzle-orm";
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "../src/db/schema";
import { slugify } from "../src/lib/utils";

const client = postgres(process.env.DATABASE_URL!, { max: 1 });
const db = drizzle(client, { schema });

type Catalog = {
  products: {
    handle: string;
    title: string;
    bodyHtml: string;
    tags: string[];
    createdAt: string;
    publishedAt: string | null;
    options: { name: string; values: string[] }[];
    variants: {
      title: string;
      sku: string | null;
      price: string;
      compareAtPrice: string | null;
      option1: string | null;
      option2: string | null;
      option3: string | null;
      available: boolean;
      grams: number;
    }[];
    images: { url: string; alt: string; width: number; height: number }[];
  }[];
  collections: { handle: string; title: string; descriptionHtml: string; products: string[] }[];
  pages: { handle: string; title: string; bodyHtml: string }[];
  posts: { handle: string; title: string; publishedAt: string; author: string; bodyHtml: string; excerpt: string }[];
  drafts: { handle: string; title: string; productType: string; images: { url: string; alt: string; width: number; height: number }[] }[];
};

const catalog: Catalog = JSON.parse(readFileSync(path.join(__dirname, "..", "seed", "catalog.json"), "utf8"));

const CATEGORY_COLLECTIONS: Record<string, string> = {
  dresses: "Dresses",
  tops: "Tops",
  skirts: "Skirts",
  jumpsuit: "Jumpsuits",
  shirts: "Shirts",
  "co-ord-sets": "Co-ord Sets",
};
const SIZE_ORDER = ["XS", "S", "M", "L", "XL", "2XL", "XXL", "3XL"];
const STARTING_STOCK = 10; // Shopify's public feed only exposes in/out of stock

const paise = (v: string | null) => (v == null ? null : Math.round(parseFloat(v) * 100));
const cleanTag = (t: string) => t.trim().toLowerCase();
const isPriceTag = (t: string) => /^(above|below)\s?\d+$/.test(t);

const EDIT_IMAGES: Record<string, string> = {
  "main-character-energy": "/images/lifestyle/hero-pink-wall.webp",
  "in-her-element": "/images/lifestyle/stone-wall.webp",
  "wander-x-wear": "/images/lifestyle/lake-wide.webp",
  "after-the-rain": "/images/lifestyle/forest-walk.webp",
  "free-spirited": "/images/lifestyle/forest-blue.webp",
  "escape-edit": "/images/lifestyle/lake-rust.webp",
};

