async function main() {
  const reset = process.argv.includes("--reset");
  const [{ count }] = await db.select({ count: sql<number>`count(*)::int` }).from(schema.products);
  if (count > 0 && !reset) {
    console.log(`Products already present (${count}). Use --reset to re-import.`);
  } else {
    if (reset) {
      await db.execute(sql`TRUNCATE collection_products, product_images, variants, products, collections, pages, blog_posts, redirects RESTART IDENTITY CASCADE`);
    }
    await importCatalog();
  }
  await attachVideos();
  await applySeoContent();
  await ensureOwner();
  await client.end();
}

/** seed/seo-content.json → collection titles, meta, guides and FAQs. Safe to re-run. */
async function applySeoContent() {
  type Entry = { seoTitle: string; seoDescription: string; intro: string; guideHtml: string; faqs: { q: string; a: string }[] };
  const data: { collections: Record<string, Entry> } = JSON.parse(readFileSync(path.join(__dirname, "..", "seed", "seo-content.json"), "utf8"));
  let n = 0;
  for (const [handle, e] of Object.entries(data.collections)) {
    const res = await db
      .update(schema.collections)
      .set({ seoTitle: e.seoTitle, seoDescription: e.seoDescription, descriptionHtml: `<p>${e.intro}</p>`, guideHtml: e.guideHtml, faqs: e.faqs })
      .where(sql`handle = ${handle}`)
      .returning({ id: schema.collections.id });
    n += res.length;
  }
  console.log(`Applied SEO content to ${n} collections.`);

  // Search-targeted journal guides (upsert by handle)
  type Post = { handle: string; title: string; seoTitle: string; seoDescription: string; excerpt: string; coverUrl: string; tags: string[]; bodyHtml: string };
  const posts: Post[] = JSON.parse(readFileSync(path.join(__dirname, "..", "seed", "posts-seo.json"), "utf8"));
  for (const p of posts) {
    await db
      .insert(schema.blogPosts)
      .values({ ...p, author: "Team Trumee", publishedAt: new Date() })
      .onConflictDoUpdate({ target: schema.blogPosts.handle, set: { title: p.title, seoTitle: p.seoTitle, seoDescription: p.seoDescription, excerpt: p.excerpt, coverUrl: p.coverUrl, tags: p.tags, bodyHtml: p.bodyHtml } });
  }
  console.log(`Upserted ${posts.length} journal guides.`);
}

/** seed/videos.json maps public/videos/<sku>.mp4 → product handle. Safe to re-run. */
async function attachVideos() {
  const map: Record<string, string | null> = JSON.parse(readFileSync(path.join(__dirname, "..", "seed", "videos.json"), "utf8"));
  let n = 0;
  for (const [sku, handle] of Object.entries(map)) {
    if (sku.startsWith("_") || !handle) continue;
    const res = await db
      .update(schema.products)
      .set({ videoUrl: `/videos/${sku}.mp4`, videoPoster: `/videos/${sku}.webp` })
      .where(sql`handle = ${handle}`)
      .returning({ id: schema.products.id });
    if (!res.length) console.warn(`video ${sku}: no product with handle ${handle}`);
    n += res.length;
  }
  console.log(`Attached ${n} product videos.`);
}

async function importCatalog() {
  // Which category does each product belong to? Drives productType.
  const typeByHandle = new Map<string, string>();
  for (const c of catalog.collections) {
    if (CATEGORY_COLLECTIONS[c.handle]) c.products.forEach((h) => typeByHandle.set(h, CATEGORY_COLLECTIONS[c.handle]));
  }

  const idByOldHandle = new Map<string, number>();
  const usedHandles = new Set<string>();
  const redirectRows: { fromPath: string; toPath: string }[] = [];

  for (const p of catalog.products) {
    let handle = slugify(p.title);
    while (usedHandles.has(handle)) handle += "-2";
    usedHandles.add(handle);
    if (handle !== p.handle) redirectRows.push({ fromPath: `/products/${p.handle}`, toPath: `/products/${handle}` });

    const sizeOpt = p.options.find((o) => o.name === "Size");
    if (sizeOpt) sizeOpt.values.sort((a, b) => SIZE_ORDER.indexOf(a) - SIZE_ORDER.indexOf(b));
    const colorOpt = p.options.find((o) => o.name === "Color");
    const options = p.options.filter((o) => !(o.name === "Title" && o.values[0] === "Default Title"));

    const [prod] = await db
      .insert(schema.products)
      .values({
        handle,
        title: p.title,
        descriptionHtml: p.bodyHtml,
        status: "active",
        productType: typeByHandle.get(p.handle) ?? "",
        tags: [...new Set(p.tags.map(cleanTag).filter((t) => !isPriceTag(t)))],
        options,
        fabric: guessFabric(p.title + " " + p.bodyHtml),
        care: "Gentle hand wash in cold water. Dry in shade. Do not bleach. Warm iron on reverse.",
        seoTitle: `${p.title} | Trumee`,
        publishedAt: p.publishedAt ? new Date(p.publishedAt) : new Date(),
        createdAt: new Date(p.createdAt),
      })
      .returning({ id: schema.products.id });
    idByOldHandle.set(p.handle, prod.id);

    await db.insert(schema.productImages).values(
      p.images.map((im, i) => ({ productId: prod.id, url: im.url, alt: im.alt, width: im.width, height: im.height, position: i })),
    );

    const sorted = [...p.variants].sort(
      (a, b) => SIZE_ORDER.indexOf(a.option1 ?? "") - SIZE_ORDER.indexOf(b.option1 ?? ""),
    );
    await db.insert(schema.variants).values(
      sorted.map((v, i) => {
        const price = paise(v.price)!;
        const compare = paise(v.compareAtPrice);
        return {
          productId: prod.id,
          title: v.title,
          sku: v.sku ? `${v.sku}-${v.option1 ?? i}` : null,
          price,
          compareAtPrice: compare && compare > price ? compare : null,
          option1: v.option1,
          option2: colorOpt ? v.option2 : v.option2,
          option3: v.option3,
          inventoryQty: v.available ? STARTING_STOCK : 0,
          weightGrams: v.grams || 300,
          position: i,
        };
      }),
    );
  }

  // Collections (skip Shopify's "home" catch-all; /collections/all replaces it)
  let pos = 0;
  for (const c of catalog.collections) {
    if (c.handle === "home") continue;
    const isCategory = !!CATEGORY_COLLECTIONS[c.handle];
    const first = catalog.products.find((p) => p.handle === c.products[0]);
    const [col] = await db
      .insert(schema.collections)
      .values({
        handle: c.handle,
        title: isCategory ? CATEGORY_COLLECTIONS[c.handle] : titleCase(c.title),
        descriptionHtml: c.descriptionHtml,
        group: isCategory ? "category" : "edit",
        imageUrl: EDIT_IMAGES[c.handle] ?? first?.images[0]?.url ?? null,
        position: pos++,
        seoTitle: `${isCategory ? CATEGORY_COLLECTIONS[c.handle] : titleCase(c.title)} | Trumee`,
      })
      .returning({ id: schema.collections.id });
    const members = c.products.map((h, i) => ({ collectionId: col.id, productId: idByOldHandle.get(h)!, position: i }));
    if (members.length) await db.insert(schema.collectionProducts).values(members.filter((m) => m.productId));
  }

  // Bestsellers from the old homepage
  const featured = [
    "misty-rose-pink-sleeveless-top-with-crochet-lace-and-schiffli-embroidery",
    "mustard-embroidered-cotton-slub-dress-with-balloon-sleeves",
    "checkered-yoke-denim-shirt-with-roll-up-sleeves",
    "vibrant-abstract-dress-with-gathered-slim-fit-details",
    "floral-crochet-lace-up-boho-top",
    "black-floral-textured-georgette-peplum-top",
    "boho-crochet-accent-square-neck-top",
    "scarlet-cotton-net-lace-waist-panel-top",
  ];
  for (const h of featured) {
    const id = idByOldHandle.get(h);
    if (id) await db.update(schema.products).set({ featured: true }).where(sql`id = ${id}`);
  }

  // 2026 collection → draft products (need price, sizes and description before publishing)
  for (const d of catalog.drafts) {
    const [prod] = await db
      .insert(schema.products)
      .values({
        handle: d.handle,
        title: d.title,
        status: "draft",
        productType: d.productType,
        tags: ["2026", "new-arrival", "needs-pricing"],
        options: [{ name: "Size", values: ["XS", "S", "M", "L", "XL"] }],
        descriptionHtml: "<p>Description coming soon.</p>",
      })
      .returning({ id: schema.products.id });
    await db.insert(schema.productImages).values(d.images.map((im, i) => ({ productId: prod.id, ...im, position: i })));
    await db.insert(schema.variants).values(
      ["XS", "S", "M", "L", "XL"].map((s, i) => ({ productId: prod.id, title: s, option1: s, price: 0, inventoryQty: 0, position: i })),
    );
  }

  // Pages
  const pageRows: { handle: string; title: string; bodyHtml: string; seoDescription?: string }[] = catalog.pages.map((p) => ({
    handle: p.handle,
    title: p.title,
    bodyHtml: p.handle === "about-us" ? ABOUT_HTML.trim() : p.bodyHtml,
  }));
  pageRows.push({ handle: "faqs", title: "Frequently Asked Questions", bodyHtml: FAQ_HTML.trim(), seoDescription: "Answers on Trumee orders, payments, COD, delivery times, returns & exchanges, sizing and account questions — all in one place." } as (typeof pageRows)[number]);
  await db.insert(schema.pages).values(pageRows);

  // Blog
  const covers = ["/images/lifestyle/lake-rust.webp", "/images/lifestyle/cafe-chair.webp", "/images/lifestyle/pink-stairs.webp"];
  await db.insert(schema.blogPosts).values(
    catalog.posts.map((p, i) => ({
      handle: p.handle,
      title: p.title,
      excerpt: p.excerpt,
      bodyHtml: p.bodyHtml,
      author: p.author,
      coverUrl: covers[i % covers.length],
      publishedAt: new Date(p.publishedAt),
      tags: ["style guide"],
    })),
  );

  redirectRows.push({ fromPath: "/collections/home", toPath: "/collections/all" });
  if (redirectRows.length) await db.insert(schema.redirects).values(redirectRows).onConflictDoNothing();

  console.log(
    `Imported ${catalog.products.length} products, ${catalog.drafts.length} drafts, ${catalog.collections.length - 1} collections, ` +
      `${pageRows.length} pages, ${catalog.posts.length} posts, ${redirectRows.length} redirects.`,
  );
}

async function ensureOwner() {
  const email = process.env.ADMIN_EMAIL;
  const password = process.env.ADMIN_PASSWORD;
  if (!email || !password) return console.warn("ADMIN_EMAIL / ADMIN_PASSWORD not set — no admin created.");
  const existing = await db.query.staff.findFirst({ where: (s, { eq }) => eq(s.email, email) });
  if (existing) return console.log(`Admin ${email} already exists.`);
  await db.insert(schema.staff).values({
    email,
    name: "Store Owner",
    role: "owner",
    passwordHash: await bcrypt.hash(password, 11),
  });
  console.log(`Created owner account ${email} (password from ADMIN_PASSWORD in .env).`);
}

function titleCase(s: string) {
  return s
    .toLowerCase()
    .replace(/\b(\w)/g, (m) => m.toUpperCase())
    .replace(/\bX\b/g, "x");
}

function guessFabric(text: string) {
  const t = text.toLowerCase();
  for (const f of ["georgette", "rayon", "cotton slub", "cotton flex", "cotton moss", "denim", "viscose", "cotton"]) {
    if (t.includes(f)) return f.replace(/\b\w/g, (m) => m.toUpperCase());
  }
  return null;
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
